    tclAppend(output, "    Owner: ");
    tclAppend(output, mds_owner(owner));
    tclAppend(output, "\n");
    if (dataLen)
    {
      sprintf(msg, "      Dtype: %-20s  Class: %-18s  Length: %u bytes\n",
